"""Inventory helpers."""


def parse_price(text):
    """Parse a price string like "$12.50" or "1,234.50" into a float."""
    cleaned = text.strip().lstrip("$")
    if "," in cleaned:
        # European style decimal comma: "12,50"
        cleaned = cleaned.replace(",", ".")
    return float(cleaned)


def total_value(items):
    """Sum price * quantity for (price_text, quantity) pairs."""
    return round(sum(parse_price(p) * q for p, q in items), 2)

import unittest

from inventory import parse_price, total_value


class ParsePriceTest(unittest.TestCase):
    def test_plain(self):
        self.assertEqual(parse_price("12.50"), 12.5)

    def test_dollar(self):
        self.assertEqual(parse_price("$3"), 3.0)

    def test_decimal_comma(self):
        self.assertEqual(parse_price("12,50"), 12.5)


class TotalValueTest(unittest.TestCase):
    def test_total(self):
        self.assertEqual(total_value([("2.00", 3), ("$1.25", 2)]), 8.5)


if __name__ == "__main__":
    unittest.main()

